323:
SELECT m."label"
FROM "molecule" m
WHERE m."molecule_id" = 'TR000';

319:
SELECT COUNT(DISTINCT c."atom_id") AS element_count
FROM "connected" c
WHERE c."bond_id" = 'TR001_3_4';

453:
SELECT DISTINCT "convertedmanacost"
FROM "cards"
WHERE "name" LIKE '%Ancestor%s Chosen%';

661:
SELECT "u"."age"
FROM "users" AS "u"
WHERE "u"."reputation" = (
    SELECT MAX("reputation") FROM "users"
)
LIMIT 1;

621:
SELECT DISTINCT b."name"
FROM "badges" b
JOIN "users" u ON u."id" = b."userid"
WHERE u."reputation" = (
    SELECT MIN("reputation") FROM "users"
);

588:
SELECT COUNT(*) AS total_comments
FROM "comments" c
WHERE c."userid" = 13;

572:
SELECT "p"."viewcount"
FROM "posts" AS "p"
WHERE "p"."title" = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

747:
SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero" s
WHERE s."full_name" IS NULL;

1377:
SELECT COUNT(*) AS president_count
FROM "member" m
WHERE m."position" LIKE '%President%';

1365:
SELECT e."expense_description"
FROM "expense" e
JOIN "budget" b ON e."link_to_budget" = b."budget_id"
WHERE b."remaining" = (
    SELECT MIN("remaining") FROM "budget"
);
